WITH lines AS (SELECT id, customer_id, created_at, coupon_codes, elem.product_id, elem.qty, elem.price, elem.promo FROM (SELECT id, customer_id, created_at, coupon_codes, EXPLODE(items) AS elem FROM carts) e) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, CASE WHEN price >= 211 THEN 'HIGH' ELSE 'LOW' END AS price_tier, CASE WHEN qty >= 5 THEN 'PREMIUM' ELSE 'STANDARD' END AS qty_tier, SUM(product_id) AS total_product_id, COUNT(*) FILTER (WHERE promo = 'SPRING10') AS spring10_rows FROM lines GROUP BY GROUPING SETS ((DATE_TRUNC('HOUR', created_at), CASE WHEN price >= 211 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN qty >= 5 THEN 'PREMIUM' ELSE 'STANDARD' END), (DATE_TRUNC('HOUR', created_at), CASE WHEN price >= 211 THEN 'HIGH' ELSE 'LOW' END), (DATE_TRUNC('HOUR', created_at)))
